      + '<div class="toolbar">' + UI.search('Search ' + repo.name + (live ? ' (live)' : ' snapshot ' + repo.snapshot), 'data-search', st.query) + chips + '<span class="muted right" style="font-size:12px">' + rows.length + ' of ' + all.length + ' in snapshot · ' + (live ? 'live search on' : 'snapshot only') + '</span></div>'
