      + UI.field('Attribution', UI.input(st.form.attribution || ((it.org || it.publisher) + ', ' + repoOf(it.repo).name + (it.repo === 'zenodo' ? ', DOI recorded' : '')), { attrs: 'data-f="attribution"' }), 'Shown on the model card or dataset manifest')
      + '</div><div class="hstack wrap gap12">' + UI.check('Licence reviewed by legal for commercial internal use', st.licenceReviewed, 'data-licrev') + (ALLOWED_LICENCES.includes(lic) || lic === 'other' ? '' : UI.btn(st.exception ? 'Exception EXC-119 requested' : 'Request licence exception', { size: 'sm', attrs: 'data-exception', disabled: st.exception })) + '</div>';
