        + UI.field('Family', UI.input(st.form.family || (it.org === 'Ollama library' ? it.id : it.id.split('/').pop().split('-')[0]), { attrs: 'data-f="family"' }))
        + UI.field('Capabilities expected', UI.input(st.form.caps || it.caps.join(', '), { attrs: 'data-f="caps"' }), 'Conformance withholds what fails')
